def test_get_view_route_200_returns_view_shape(client, stub_service):
    http, _Session, _user = client
    resp = http.get("/api/mobo/post-trade-allocation")
    assert resp.status_code == 200, resp.text
    body = resp.json()
    assert body["tradeDate"] == "2026-06-03"
    assert body["models"][0]["clientShares"][0]["pct"] == 20


