# --- Guards: 403 for non-MOBO/non-ADMIN, all three routes -----------------------


@pytest.mark.parametrize(
    "method,path",
    [
        ("GET", "/api/mobo/post-trade-allocation"),
        ("GET", "/api/mobo/post-trade-allocation/runs"),
        ("POST", "/api/mobo/post-trade-allocation/run"),
    ],
)
@pytest.mark.parametrize("role", [AdminRole.RM, AdminRole.PM, AdminRole.PC, AdminRole.COMPLIANCE])
def test_non_mobo_non_admin_gets_403_on_all_routes(client, method, path, role):
    http, Session, stub_user = client
    db = Session()
    db.query(AdminProfile).filter_by(user_id=stub_user.id).update({"role": role})
    db.commit()
    db.close()

    resp = http.request(method, path, json={} if method == "POST" else None)
    assert resp.status_code == 403


@pytest.mark.parametrize(
    "method,path",
    [
        ("GET", "/api/mobo/post-trade-allocation"),
        ("GET", "/api/mobo/post-trade-allocation/runs"),
        ("POST", "/api/mobo/post-trade-allocation/run"),
    ],
)
def test_admin_role_passes_all_routes(client, method, path):
    http, Session, stub_user = client
    db = Session()
    db.query(AdminProfile).filter_by(user_id=stub_user.id).update({"role": AdminRole.ADMIN})
    db.commit()
    db.close()

    resp = http.request(method, path, json={} if method == "POST" else None)
    assert resp.status_code == 200


def test_all_three_routes_resolve_in_openapi():
    from app.main import app as real_app

    paths = real_app.openapi()["paths"]
    assert "/api/mobo/post-trade-allocation" in paths
    assert "/api/mobo/post-trade-allocation/runs" in paths
    assert "/api/mobo/post-trade-allocation/run" in paths
    assert "get" in paths["/api/mobo/post-trade-allocation"]
    assert "get" in paths["/api/mobo/post-trade-allocation/runs"]
    assert "post" in paths["/api/mobo/post-trade-allocation/run"]
